import scholarshipDemo from "../../../config/services/scholarship_demo.json" with { type: "json" };
import { ServiceDefinition } from "./schemas";

/**
 * Service definitions bundled with the code. The database `services` table is
 * seeded from these (supabase/seed.sql is generated by `npm run db:seed-sql`).
 */
export const BUNDLED_SERVICES: readonly ServiceDefinition[] = [ServiceDefinition.parse(scholarshipDemo)];

export function getBundledService(slug: string): ServiceDefinition | undefined {
  return BUNDLED_SERVICES.find((s) => s.slug === slug);
}
